-- Frost Mage rework - talent tree content, pure-data pass 1 (docs/frost-mage-talent-tree-content-handoff.md
-- "Suggested order" step 1): retunes/rescopes for the 11 confirmed-or-likely-pure-data talent rows,
-- plus the 3 rank-count trims (Improved Frostbolt 5->2, Arctic Winds 5->3, Chilled to the Bone 5->3) done
-- alongside them since the trimmed rank count and the retuned numbers aren't independently decidable.
-- Piercing Ice (61), Shatter (67) and Cold as Ice (1737) needed zero changes - their pulled data already
-- matched the redesign spec's numbers exactly; not included here since nothing changed.
--
-- Known gap: Chilled to the Bone's slow-on-chill effect is scoped to Frostbolt + Cone of Cold via
-- SpellClassMask; Frozen Orb (200007) carries no SpellFamilyFlags of its own (it's a scripted trigger
-- spell), so a classmask-scoped SpellMod can't reach it yet. Left out rather than guessed at - needs
-- either a minted classmask bit for 200007 or C++ handling in spell_mage_frozen_orb.

DELETE FROM `spell_dbc` WHERE `ID` IN (11070, 11160, 11207, 12473, 12518, 12519, 12672, 16757, 16758, 29438, 29439, 29440, 31670, 31672, 31674, 31675, 31676, 44566, 44567, 44568, 55094);

DELETE FROM `talent_dbc` WHERE `ID` IN (37, 1738, 1856);
